with open('/Users/charles/Desktop/folder/gomoku-react/apps/web/src/components/GameLobby.jsx', 'r') as f:
    content = f.read()

# Find exact match
search = '          <div className="text-[11px] text-theme-muted tracking-widest mb-3 font-theme">\n            QUICK JOIN'
idx = content.find(search)
if idx >= 0:
    print(f"Found at index {idx}")
    print(repr(content[idx:idx+200]))
else:
    # Try with different spacing
    lines = content.split('\n')
    for i, line in enumerate(lines):
        if 'QUICK JOIN' in line:
            print(f"Line {i+1}: {repr(line)}")
            if i > 0:
                print(f"Line {i}: {repr(lines[i-1])}")
"}

