              ))}
            </div>
          </div>
        )}
        {status === 'error' && <ErrorState onRetry={handleRetry} />}
        {status === 'loaded' && picks.length === 0 && <EmptyState />}
      </main>

      {/* ── 浮动操作按钮 ──────────────────────────────────────────────────── */}
      <FloatingActions
        onClose={() => handleClose()}
        onLike={() => handleLike()}
        onBookmark={() => handleBookmark()}
      />

      {/* ── 底部导航 ──────────────────────────────────────────────────────── */}
      <BottomNav active="discover" />
    </div>
  )
}
